function e(from, to, label, file, quote, ranges, blurb) {
    const id = `${from}__${to}__${label.replace(/[^a-z0-9]+/gi, "-").replace(/^-|-$/g, "").toLowerCase()}`;
    return { id, from, to, label, file, quote, ranges, blurb };
}

